import json,hashlib,re,statistics
FILES=['raw/inf_5.0.json','raw/inf_5.1.json','raw/inf_6.0.json','raw/inf_6.1.json']; RAW={f:open(f,'rb').read() for f in FILES}
V5=json.loads(RAW[FILES[0]]); V51=json.loads(RAW[FILES[1]]); V0=json.loads(RAW[FILES[2]]); B=list(json.loads(RAW[FILES[3]]).values()); s=str; pc=lambda x,y:100*(x/y-1)
def mk(i,q,calc,st,got,out,note): return dict(id=i,quote=q,calc=calc,stated=st,delivered=got,outcome=out,note=note,label_mismatch=False)
def b(org,sysn,m,sc,div='closed',n=None):
    r=[x for x in B if x['Organization']==org and sysn in x['SystemName'] and x['Model']==m and x['Scenario'].lower()==sc.lower() and x['Division']==div and (n is None or x['total_accelerators']==n)]
    assert len(r)==1,(org,sysn,m,sc,div,n,len(r)); return r[0]['Result']
def a(i,m,sc,cat='closed'):
    r=[x for x in V0 if x['ID']==i and x['Model']==m and x['Scenario']==sc and x['Category']==cat]; assert len(r)==1,(i,m,sc,len(r)); return r[0]['Performance_Result']
AM=[];CR=[]
