AM.append(mk('AV2','increased GPT-OSS-120B throughput by 28% in Offline and 38% in Server, while Wan-2.2 SingleStream performance increased 70%','AMD 8-GPU MI355X entry, v6.0 entries 6.0-0002 and 6.0-0103 against the v6.1 entry','+28% Offline, +38% Server, Wan-2.2 SingleStream +70%',f'GPT-OSS-120B Offline {g0o:,.0f} to {go:,.0f} ({pc(go,g0o):+.1f}%), Server {g0s:,.0f} to {gs:,.0f} ({pc(gs,g0s):+.1f}%). Wan-2.2 SingleStream {w0:.2f} s to {w1:.2f} s, {pc(w0/w1,1):+.1f}% faster, {100*(1-w1/w0):.1f}% shorter','CONSISTENT' if abs(pc(go,g0o)-28)<0.6 and abs(pc(gs,g0s)-38)<0.6 and abs(pc(w0/w1,1)-70)<1 else 'BELOW','The 70% is a speedup (the latency is 41% shorter). The v6.0 Wan-2.2 entry is in the open division. The v6.1 entry is closed.'))
x72o,x72s=b('AMD','9x8xMI355X','gpt-oss-120b','Offline'),b('AMD','9x8xMI355X','gpt-oss-120b','Server'); x94o,x94s=a('6.0-0003','gpt-oss-120b','Offline'),a('6.0-0003','gpt-oss-120b','Server')
AM.append(mk('AV3','72 AMD Instinct MI355X GPUs in MLPerf Inference round 6.1 delivered more GPT-OSS-120B throughput than 94 GPUs deliveredin previous round 6.0.','AMD 72-GPU v6.1 entry against AMD v6.0 entry 6.0-0003 (94 GPUs by its accelerator name, 96 in the total column)','72 GPUs in 6.1 above 94 GPUs in 6.0',f'Offline {x72o:,.0f} against {x94o:,.0f} ({pc(x72o,x94o):+.1f}%). Server {x72s:,.0f} against {x94s:,.0f} ({pc(x72s,x94s):+.1f}%)','CONSISTENT' if x72o>x94o and x72s>x94s else 'BELOW','The v6.0 entry total column says 96 accelerators. Its accelerator name says 94.'))
