AM.append(mk('AV4','AMD expanded GPT-OSS-120B from 8 to 72 AMD Instinct MI355X GPUs, a ninefold increase in GPU count, while retaining 95% scale efficiency in both Offline and Server.','AMD 72-GPU entry against 9 times the AMD 8-GPU entry, GPT-OSS-120B','95% in both',f'Offline {x72o:,.0f} against 9 x {go:,.0f} = {e1:.1f}%. Server {x72s:,.0f} against 9 x {gs:,.0f} = {e2:.1f}%','CONSISTENT' if abs(e1-95)<0.6 and abs(e2-95)<0.6 else 'BELOW',''))
def mx(L,key,unit,model=None):
    return max(((x[key],x.get('Organization',x.get('Submitter')),x['Model'],x['Scenario']) for x in L if 'oken' in s(x.get(unit)) and (model is None or x['Model']==model)))
