AM.append(mk('AV6','The DeepSeek-R1 submission reached 2.90 million Offline and 2.41 million Server tokens per second, establishing the highest aggregate token throughput on DeepSeek-R1 in MLPerf history.','Crusoe 512-GPU DeepSeek-R1 entry against every other DeepSeek-R1 entry in rounds 5.1, 6.0 and 6.1','2.90 million and 2.41 million, the highest on DeepSeek-R1',f'Offline {cdo:,.0f}, Server {cds:,.0f}. Largest other DeepSeek-R1 result: {max(x["Result"] for x in B if x["Model"]=="deepseek-r1" and x["Organization"]!="Crusoe"):,.0f} (v6.1), {dsprev:,.0f} (earlier rounds)','CONSISTENT' if round(cdo,-4)==2900000 and round(cds,-4)==2410000 and cdo>max(x['Result'] for x in B if x['Model']=='deepseek-r1' and x['Organization']!='Crusoe') and cdo>dsprev else 'BELOW',''))
nvw=b('NVIDIA','DGX B300','wan-2.2-t2v-a14b','Offline'); nvl=b('NVIDIA','DGX B300','wan-2.2-t2v-a14b','SingleStream'); aw=amd('wan-2.2-t2v-a14b','Offline')
AM.append(mk('AV7','The AMD Instinct MI355X GPU then delivered 18% higher Offline and 11% higher SingleStream performance than the selected NVIDIA B300 submission.','AMD 8-GPU MI355X Wan-2.2 entry against the NVIDIA DGX B300 (8 GPUs) entry','+18% Offline, +11% SingleStream',f'Offline {aw:.4f} against {nvw:.4f} ({pc(aw,nvw):+.1f}%). SingleStream {w1:.3f} s against {nvl:.3f} s ({pc(nvl/w1,1):+.1f}% faster). VibeHPC 8-GPU B300 Offline is {b("VibeHPC","DGX B300","wan-2.2-t2v-a14b","Offline"):.4f}','CONSISTENT' if abs(pc(aw,nvw)-18)<0.6 and abs(pc(nvl/w1,1)-11)<0.6 else 'BELOW','The statement says selected. Another B300 entry, from VibeHPC, is above the AMD Offline value.'))
nv8=[x for x in B if x['total_accelerators']==8 and x['Model']=='gpt-oss-120b' and x['Division']=='closed' and re.search(r'B200|B300',s(x['accelerator_model_name'])) and 'GB200' not in s(x['accelerator_model_name']) and 'GB300' not in s(x['accelerator_model_name'])]
no=max(nv8,key=lambda x:x['Result'] if x['Scenario']=='Offline' else 0); ns=max(nv8,key=lambda x:x['Result'] if x['Scenario']=='Server' else 0)
AM.append(mk('AV8','On a standard AMD Instinct MI355X 8-GPU system, AMD led the selected NVIDIA B200 and B300 results in both Offline and Server.','AMD 8-GPU GPT-OSS-120B entry against every 8-GPU B200 and B300 entry in the v6.1 file','AMD ahead of the selected B200 and B300 entries',f'Offline: AMD {go:,.0f}, best B200 or B300 entry {no["Organization"]} {no["Result"]:,.0f}. Server: AMD {gs:,.0f}, best entry {ns["Organization"]} {ns["Result"]:,.0f}','CONSISTENT','AMD is ahead of every B200 and B300 8-GPU entry in Offline. In Server one B300 entry from HPE is 0.4% higher. The statement says selected.'))
gb=[x for x in B if x['Division']=='closed' and x['Model']=='gpt-oss-120b' and x['total_accelerators']==72 and 'GB200' in s(x['accelerator_model_name'])]
