def bb(org,sn,m,sc):
    if sn.startswith('='):
        r=[x for x in B if x['Organization']==org and x['SystemName']==sn[1:] and x['Model']==m and x['Scenario']==sc and x['Division']=='closed']
    else: r=[x for x in B if x['Organization']==org and sn in x['SystemName'] and x['Model']==m and x['Scenario']==sc and x['Division']=='closed' and x['total_accelerators']==8]
    return r[0]['Result'] if len(r)==1 else None
amdrows=[(x['Model'],x['Scenario'],x['Result']) for x in B if x['Organization']=='AMD' and 'smci355' in x['SystemName'] and x['Division']=='closed' and x['Scenario'] in('Offline','Server','Interactive')]
for org,sn in partners:
    for m,sc,ar in amdrows:
        v=bb(org,sn,m,sc)
        if v: ratios.append(100*v/ar)
